#include "dfre/mission_terrain_content.hpp"
#include "dfre/network.hpp"
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <cassert>
#include <algorithm>
#include <iostream>
namespace {using U=std::uint32_t;
template<class F>bool fails(F f){try{f();}catch(const std::exception&){return true;}return false;}
void raw(){using namespace dfre;std::array<U,256>table{};for(U i=0;i<256;++i){U v=i<<24;for(U bit=0;bit<8;++bit)v=(v<<1)^((v&0x80000000u)?0x04c11db7u:0u);table[i]=v;}const std::string bytes="123456789";U reads=0;std::vector<std::pair<U,U>>order;MissionClientAddedBindings b;b.read=[&](U a,U width){++reads;order.emplace_back(a,width);if(width==1){assert(a>=0x1200000&&a<0x1200000+bytes.size());return U(std::uint8_t(bytes[a-0x1200000]));}assert(width==4&&a>=0x4f8720&&a<0x4f8b20);return table[(a-0x4f8720)/4];};assert(mission_terrain_crc(b,0x1200000,9)==0x0376e6e7);assert(reads==18);for(U i=0;i<9;++i){assert(order[i*2].first==0x1200000+i&&order[i*2].second==1);assert(order[i*2+1].second==4);}assert(fails([&]{mission_terrain_crc({},0,1);}));reads=0;b.read=[&](U a,U width){++reads;if(reads==3)throw std::runtime_error("Bounded zero-count source read");return width==1?U(a&255):table[0];};assert(fails([&]{mission_terrain_crc(b,0xffffffff,0);}));assert(reads==3);U mutated=0;b.read=[&](U a,U width){if(width==1){table[255u^std::uint8_t('A')]=0x12345678;return U('A');}assert(a==0x4f8720+4*(255u^std::uint8_t('A')));++mutated;return table[(a-0x4f8720)/4];};assert(mission_terrain_crc(b,0,1)==(0xffffff00u^0x12345678u)&&mutated==1);std::cout<<"raw CRC/current table/read order/zero-count fault checks passed\n";}
void actual(const std::filesystem::path&game){using namespace dfre;AssetStore assets(game);U missions=0,changed_sky=0,wet=0;for(const auto&name:assets.missions()){auto runtime=load_terrain_runtime(assets,name);const auto values=mission_terrain_content(assets,runtime);++missions;if(runtime.sky)changed_sky+=values[7]!=crc32_mpeg2(runtime.sky->pixels.data(),runtime.sky->pixels.size());if(runtime.water_height)++wet;else assert(values[6]==0);if(name=="C05M07.BMS"){const std::array<U,9>expected{0xa2477c45,0xd7311b7a,0x54e1c724,0xa1073e01,0x6b14e89e,0xb89056f6,0,0x2fbcda47,0x7e501cb7};assert(values==expected&&runtime.water_height==0);auto runtime32=load_terrain_runtime(assets,name,32);assert(mission_terrain_content(assets,runtime32)==values);for(auto&f:runtime.config.fields)if(f.name=="elev_map")f.values={"DFRE_REQUIRED_CONTENT_MISSING"};assert(fails([&]{mission_terrain_content(assets,runtime);}));}if(name=="C06M01.BMS"){const auto before=values;runtime.geometry=TerrainGeometry(AssetBytes(1024*1024),AssetBytes(1024*1024),std::vector<U>(65536));std::fill(runtime.color.pixels.begin(),runtime.color.pixels.end(),0);if(runtime.sky)std::fill(runtime.sky->pixels.begin(),runtime.sky->pixels.end(),0);assert(mission_terrain_content(assets,runtime)==before);runtime.water_height=1;runtime.water.reset();assert(fails([&]{mission_terrain_content(assets,runtime);}));}}
assert(missions==62&&changed_sky>0&&wet>0);std::cout<<"actual terrain content missions="<<missions<<" changed_sky="<<changed_sky<<" water="<<wet<<" device_output0 network_output0\n";}
}
int main(int argc,char**argv){try{raw();if(argc==2)actual(argv[1]);else if(argc!=1)throw std::runtime_error("Use: native_mission_terrain_content [GAME_FOLDER]");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
